// Why Code: no native node decodes EUC-KR HTML and formats rows into <=200-char chunks (Kakao text limit).
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const html = new TextDecoder('euc-kr').decode(buf);

const kst = new Date(Date.now() + 9 * 3600 * 1000);
const todayStr = kst.toISOString().slice(0, 10);
const today = new Date(todayStr + 'T00:00:00Z');
const weekEnd = new Date(today.getTime() + 6 * 86400000);
const strip = (s) => s.replace(/<[^>]*>/g, '').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();

const tbody = (html.split('<tbody>')[1] || '').split('</tbody>')[0];
const pad = (n) => String(n).padStart(2, '0');
const rows = [];
for (const tr of tbody.split(/<tr[\s>]/).slice(1)) {
  const tds = [...tr.matchAll(/<td[^>]*>([\s\S]*?)<\/td>/g)].map((m) => strip(m[1]));
  if (tds.length < 4) continue;
  const m = tds[1].match(/(\d{4})\.(\d{2})\.(\d{2})\s*~\s*(?:(\d{2})\.)?(\d{2})/);
  if (!m) continue;
  const y = +m[1];
  const sm = +m[2];
  const sd = +m[3];
  const em = m[4] ? +m[4] : sm;
  const ed = +m[5];
  const ey = em < sm ? y + 1 : y;
  const start = new Date(Date.UTC(y, sm - 1, sd));
  const end = new Date(Date.UTC(ey, em - 1, ed));
  const price = tds[2] && tds[2] !== '-' ? '확정 ' + tds[2] : '희망 ' + tds[3];
  rows.push({ name: tds[0], start, end, label: `${pad(sm)}.${pad(sd)}~${pad(em)}.${pad(ed)}`, price });
}

const upcoming = rows.filter((r) => r.end >= today).sort((a, b) => a.start - b.start);
const thisWeek = upcoming.filter((r) => r.start <= weekEnd);
const picked = upcoming.slice(0, 10);
const md = todayStr.slice(5).replace('-', '.');

if (!picked.length) {
  return [{ json: { text: `[공모주 ${md}] 진행/예정 공모주가 없습니다.` } }];
}
const lines = picked.map((r, i) => `${i + 1}. ${r.name} ${r.label} ${r.price}`);
const head = thisWeek.length
  ? `[공모주 ${md}] 이번 주 청약 ${thisWeek.length}건`
  : `[공모주 ${md}] 이번 주 청약 없음, 다가오는 일정`;

const chunks = [];
let cur = [];
for (const l of lines) {
  if ((cur.join('\n') + '\n' + l).length > 140) { chunks.push(cur); cur = []; }
  cur.push(l);
}
if (cur.length) chunks.push(cur);
return chunks.map((c, i) => ({
  json: { text: `${i === 0 ? head : `[공모주 ${md}]`} (${i + 1}/${chunks.length})\n${c.join('\n')}`.slice(0, 200) },
}));
